import{_ as t,o as s,c as n,ah as o}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse(`{"title":"Screenplay Update: Scene 42 - The Aesthetic of the Small Things","description":"A hectic press conference where Minister Gönner explains the 'Pointillism of Money' as an art form.","frontmatter":{"title":"Screenplay Update: Scene 42 - The Aesthetic of the Small Things","description":"A hectic press conference where Minister Gönner explains the 'Pointillism of Money' as an art form.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/szene-aesthetik-der-kleinigkeit.md","filePath":"en/logbuch/szene-aesthetik-der-kleinigkeit.md"}`),a={name:"en/logbuch/szene-aesthetik-der-kleinigkeit.md"};function r(i,e,l,h,c,p){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="screenplay-update-scene-42-the-aesthetic-of-the-small-things" tabindex="-1">Screenplay Update: Scene 42 - The Aesthetic of the Small Things <a class="header-anchor" href="#screenplay-update-scene-42-the-aesthetic-of-the-small-things" aria-label="Permalink to &quot;Screenplay Update: Scene 42 - The Aesthetic of the Small Things&quot;">​</a></h1><p><strong>STYLE:</strong> A hectic press conference. Overexposed faces, the flashbulbs of the photographers act like a stroboscope. Microphones jut into the frame like black lances.</p><p><strong>CAST:</strong></p><ul><li><strong>Minister Dr. Gernot Gönner:</strong> An actor with perfectly gelled hair and a smile that sits as firmly as his tie.</li><li><strong>Journalists:</strong> A chorus of critical voices from off-screen.</li></ul><hr><p><strong>INT. PRESS CENTER - DAY</strong></p><p>Minister Gönner stands at the podium. He doesn&#39;t look caught, but rather... academically offended.</p><p><strong>JOURNALIST (OFF)</strong> Mr. Minister, the list of donations from Mrs. Horten is almost three meters long. All amounts just below the reporting threshold. That can&#39;t be a coincidence!</p><p><strong>GÖNNER</strong> (takes a deep breath, smiles pitifully) Do you know what the problem of today&#39;s time is? A glaring lack of a sense of aesthetics. You see a list of numbers. I see a work of art.</p><p>He makes an expansive gesture with his hands.</p><p><strong>GÖNNER</strong> Mrs. Horten is a patron of pointillism. You know Seurat? Signac? These great spirits understood that the truth does not lie in the large, coarse brushstroke. The truth is composed of thousands of tiny, glowing dots.</p><p><strong>JOURNALIST (OFF)</strong> We&#39;re talking about 49,000-euro morsels past the Court of Audit!</p><p><strong>GÖNNER</strong> (interrupts him gently) I&#39;m talking about the freedom of art! If a lady of the world decides to express her affection for democracy in many small, tender gestures – who are we to impose a coarse, bureaucratic grid on her?</p><p>He leans confidentially towards the microphone.</p><p><strong>GÖNNER</strong> A mountain consists of grains of sand. Would you declare a grain of sand at customs? No. Only when it&#39;s a mountain. But for us... for us, it&#39;s a beach. And on a beach, it&#39;s just easier to govern.</p><p><strong>JOURNALIST (OFF)</strong> That&#39;s pure donation splitting to circumvent transparency!</p><p><strong>GÖNNER</strong> (adjusts his tie) Transparency is a beautiful word. But glass is also transparent, and yet people are constantly running into it. We prefer the soft light of discretion. That&#39;s not a circumvention, that&#39;s... political landscape maintenance.</p><p><strong>FADE TO BLACK.</strong></p>',18)])])}const f=t(a,[["render",r]]);export{g as __pageData,f as default};
